<?php
declare(strict_types=1);

require_once 'connection/config.php';
require_once '__init.php';
require_once 'inc/StudentLearningJourney.php';
require_once 'inc/RevisionPlan.php';

$pageName = 'revision_plans';
$subPageName = 'revision_plans';
$conn = db();
$base = rtrim((string) ($baseUrl ?? mmh_current_request_base_url()), '/');
$escape = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
$courses = mmh_revision_courses($conn);
$templateId = (int) ($_GET['template_id'] ?? 0);
$versionId = (int) ($_GET['version_id'] ?? 0);
$selectedCourse = trim((string) ($_GET['course_id'] ?? ''));
$templates = mmh_revision_templates($conn, true);
if ($templateId > 0) {
    $selectedTemplate = mmh_revision_template($conn, $templateId);
    if ($selectedTemplate) $selectedCourse = (string) $selectedTemplate['course_id'];
} else {
    $selectedTemplate = null;
}
if ($selectedCourse === '' && $courses) $selectedCourse = (string) $courses[0]['course_id'];
if (!$selectedTemplate && $selectedCourse !== '') {
    foreach ($templates as $candidate) {
        if ((string) $candidate['course_id'] === $selectedCourse) { $templateId = (int) $candidate['id']; $selectedTemplate = mmh_revision_template($conn, $templateId); break; }
    }
}
$selectedVersion = null;
if ($selectedTemplate) {
    $versionId = $versionId > 0 ? $versionId : mmh_revision_latest_version_id($conn, $templateId);
    $selectedVersion = $versionId > 0 ? mmh_revision_version($conn, $versionId) : null;
    if (!$selectedVersion || (int) $selectedVersion['template_id'] !== $templateId) {
        $versionId = mmh_revision_latest_version_id($conn, $templateId);
        $selectedVersion = $versionId > 0 ? mmh_revision_version($conn, $versionId) : null;
    }
}
$availableItems = $selectedTemplate ? mmh_revision_course_items($conn, (string) $selectedTemplate['course_id']) : [];
$flash = $_SESSION['revision_plan_flash'] ?? null;
unset($_SESSION['revision_plan_flash']);
$structure = ['batches' => $selectedVersion['batches'] ?? []];
$resourceRows = $selectedVersion['resources'] ?? [];
$itemOptions = [];
foreach ($availableItems as $item) {
    $itemOptions[] = ['id' => (string) ($item['item_id'] ?? ''), 'title' => (string) ($item['item_title'] ?? 'Course Item'), 'section' => (string) ($item['section_title'] ?? 'Course content')];
}
$resourceOptions = array_map(static fn(array $row): array => ['id' => (int) $row['id'], 'name' => (string) $row['display_name']], $resourceRows);
?>
