ame="resource_type" data-resource-type><option value="uploaded_pdf">Uploaded PDF</option><option value="external_link">HTTPS external link</option><option value="course_item">Existing Course Item</option></select></label><label class="revision-field full" data-resource-url><span>HTTPS URL</span><input name="external_url" type="url" placeholder="https://..." data-resource-url-input></label><label class="revision-field full d-none" data-resource-file><span>PDF file</span><input name="resource_file" type="file" accept="application/pdf"></label><label class="revision-field full d-none" data-resource-item><span>Course Item</span><select name="linked_course_item_id"><?php foreach ($itemOptions as $item): ?><option value="<?= $escape($item['id']) ?>"><?= $escape($item['title'] . ' · ' . $item['section']) ?></option><?php endforeach; ?></select></label><div class="revision-actions full"><button class="btn btn-outline-primary" type="submit">Add Material</button><span class="revision-help">PDF files are stored under the private application storage root.</span></div></form><?php endif; ?></section><?php endif; ?>
